// Generated by vibelang from src/context/format.ts; the migrate flow writes it again with each batch.
export function createSessionContextFormatter(locale) {
    // The fields luxon's DATETIME_MED preset passed to Intl; output is identical.
    const dateTime = new Intl.DateTimeFormat(locale, {
        year: "numeric",
        month: "short",
        day: "numeric",
        hour: "numeric",
        minute: "numeric",
    });
    return {
        number(value) {
            if (value === undefined)
                return "—";
            if (value === null)
                return "—";
            return value.toLocaleString(locale);
        },
        percent(value) {
            if (value === undefined)
                return "—";
            if (value === null)
                return "—";
            return value.toLocaleString(locale) + "%";
        },
        time(value) {
            if (!value)
                return "—";
            return dateTime.format(value);
        },
    };
}
